type HistoryPanelProps = {
  open: boolean
  onToggle: () => void
}

export default function HistoryPanel({ open, onToggle }: HistoryPanelProps) {
  const mockHistoryData = [
    {
      id: 1,
      title: "Como programar em Python",
      type: "MP4",
      quality: "1080p",
      duration: "15:30",
      size: "245MB",
      date: "2024-01-15"
    },
    {
      id: 2,
      title: "Tutorial Next.js",
      type: "MP3",
      quality: "320kbps",
      duration: "08:45",
      size: "12MB",
      date: "2024-01-14"
    }
  ]

  return (
    <div className="mt-4 bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 dark:border-gray-700">
        <span className="font-semibold text-gray-700 dark:text-gray-200">History</span>
        <div className="flex gap-2">
          <button className="w-8 h-8 flex items-center justify-center hover:bg-gray-100 dark:hover:bg-gray-700 rounded">
            <span className="text-gray-500">⊞</span>
          </button>
          <button 
            onClick={onToggle} 
            className="w-8 h-8 flex items-center justify-center hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
          >
            <span className={`text-gray-500 transform transition-transform ${open ? 'rotate-180' : ''}`}>
              ▼
            </span>
          </button>
        </div>
      </div>
      
      {open && (
        <div className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {mockHistoryData.map((item) => (
              <div key={item.id} className="p-3 bg-gray-50 dark:bg-gray-700 rounded-lg border border-gray-200 dark:border-gray-600">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900 rounded flex items-center justify-center">
                      <span className="text-blue-600 dark:text-blue-300 text-sm">
                        {item.type === 'MP4' ? '▶' : '♪'}
                      </span>
                    </div>
                    <div>
                      <div className="font-medium text-gray-900 dark:text-gray-100 text-sm">
                        {item.title}
                      </div>
                      <div className="text-xs text-gray-500 dark:text-gray-400">
                        {item.type} - {item.quality} • {item.duration} • {item.size}
                      </div>
                      <div className="text-xs text-gray-400 dark:text-gray-500">
                        {item.date}
                      </div>
                    </div>
                  </div>
                  <button className="text-red-500 hover:text-red-700 p-1">
                    <span className="text-sm">🗑</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}